	Spin(mwheel, x_axis, rad(499.88), rad(149.96))
	Spin(fwheel, x_axis, rad(499.88), rad(149.96))
end

function script.StopMoving()
	StopSpin(rwheel, x_axis)
	StopSpin(mwheel, x_axis)
	StopSpin(fwheel, x_axis)
end

function script.SweetSpot()
	return base
end

function script.AimFromWeapon(num)
